evidence.answerQuery:
PREFIX agents: <https://data.oireachtas.ie/ontology#>
PREFIX dcat: <http://www.w3.org/ns/dcat#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX eli: <http://data.europa.eu/eli/ontology#>
PREFIX eli-dl: <http://data.europa.eu/eli/eli-draft-legislation-ontology#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX members: <https://data.oireachtas.ie/ontology/members#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?member ?episode ?identity ?affiliationLabel ?start ?end ?party ?membership ?term ?dateRange ?memberGraph WHERE {
  VALUES ?member { <https://data.oireachtas.ie/ie/oireachtas/member/id/Stephen-Donnelly.D.2011-03-09> }
  GRAPH ?memberGraph {
    <https://data.oireachtas.ie/ie/oireachtas/member/id/Stephen-Donnelly.D.2011-03-09> a agents:Member ; members:hasMembersMembership ?episode .
    ?episode a members:PartyMembership ; members:inOireachtasMembership ?membership ; members:isPartyMembershipOf ?party .
    ?membership members:inHouseTerm ?term .
    OPTIONAL { ?episode members:hasMembershipDateRange ?dateRange .
      ?dateRange a members:DateRange .
      OPTIONAL { ?dateRange members:StartDate ?start . }
      OPTIONAL { ?dateRange members:EndDate ?end . }
    }
  }
  GRAPH <https://data.oireachtas.ie/graph/parties> { ?party a members:ParliamentaryParty ; members:activeDuringTerm ?term . }
  GRAPH <https://data.oireachtas.ie/graph/houses> { ?term a ?termType . }
  VALUES ?termType { agents:DailTerm agents:SeanadTerm }
  OPTIONAL { GRAPH <https://data.oireachtas.ie/graph/political-affiliations/identities> {
    ?party members:hasPoliticalAffiliationIdentity ?identity .
    ?identity a members:PoliticalAffiliationIdentity .
    OPTIONAL { ?identity skos:prefLabel ?affiliationLabel . FILTER(LANG(?affiliationLabel) = "en") }
  } }
} ORDER BY ?affiliationLabel ?identity ?episode ?start ?end ?member
LIMIT 100

